# The program decides what to wear from the temperature.
temperature = 12

if temperature >= 25:
    print("It is hot: wear a T-shirt.")
elif temperature >= 15:
    print("It is mild: a light jacket will do.")
elif temperature >= 5:
    print("It is cool: take a coat.")
else:
    print("It is freezing: coat, scarf and gloves!")

# Without elif or else: the block runs only if it is true.
raining = True
if raining:
    print("And take an umbrella.")

# if ... else chooses between exactly two paths.
basket = 42.80
if basket >= 50:
    print("Free delivery!")
else:
    print(f"Add {50 - basket:.2f} euros more for free delivery.")

print("Have a nice day.")  # not indented: it always runs

# Several parameters; the last one has a default value.
def order_total(price, quantity, discount=0):
    total = price * quantity
    return total - total * discount / 100

print(order_total(4.0, 3))                     # no discount
print(order_total(4.0, 3, 25))                 # 25 % off
print(order_total(quantity=2, price=10.0, discount=10))  # by name

# return can give back several values at once (a tuple).
def summary(marks):
    average = sum(marks) / len(marks)
    return min(marks), max(marks), round(average, 1)

low, high, avg = summary([6, 9, 7, 10, 8])
print(f"Lowest {low}, highest {high}, average {avg}")

# return also ends the function straight away.
def grade(mark):
    if mark >= 9:
        return "Outstanding"
    if mark >= 5:
        return "Pass"
    return "Keep trying"

for mark in [9.5, 7.2, 5.0, 3.8]:
    print(mark, "->", grade(mark))

# A function without return gives back None.
def cheer(name):
    print("Well done,", name)

print(cheer("Lola"))

# int() fails with text that is not a number: try catches it.
answers = ["42", "seven", "3.5", "15"]
total = 0

for text in answers:
    try:
        number = int(text)
        total += number
        print(f"'{text}' -> {number}")
    except ValueError:
        print(f"'{text}' is not a whole number, skipped")
print("Total:", total)

# Different errors, different except blocks.
def slices_each(pizzas, people):
    try:
        slices = pizzas * 8 // people
    except ZeroDivisionError:
        print("Nobody to share with!")
    except TypeError:
        print("People must be a number.")
    else:  # runs only if there was no error
        print(f"{people} people get {slices} slices each")

slices_each(3, 4)
slices_each(3, 0)
slices_each(3, "four")

# as gives you the error itself, with its message.
prices = {"tea": 1.5, "coffee": 1.8}
try:
    print(prices["juice"])
except KeyError as error:
    print("No price for", error)

# Grade report: files, strings, lists, dicts, functions and errors.
def grade(mark):
    if mark >= 9:
        return "A"
    if mark >= 7:
        return "B"
    if mark >= 5:
        return "C"
    return "F"

with open("marks.txt", "w") as file:
    file.write("Ana: 8, 9.5, 7\nBen: 4, 6, five\nCarla: 9, 10, 9.5\nDani: 3, 5, 4\n")
averages = {}
with open("marks.txt") as file:
    for line in file:
        name, text = line.split(":")
        marks = []
        for part in text.split(","):
            try:
                marks.append(float(part))
            except ValueError:
                print(f"{name}: '{part.strip()}' is not a mark, skipped")
        averages[name] = sum(marks) / len(marks)

print(f"{'Student':<8}{'Avg':>6}  Grade")
passed, best_name, best = [], "", 0
for name, avg in averages.items():
    print(f"{name:<8}{avg:>6.2f}  {grade(avg)}")
    if avg >= 5:
        passed.append(name)
    if avg > best:
        best_name, best = name, avg
print("Passed:", ", ".join(passed))
print(f"Best average: {best_name} ({best:.2f})")
